fn same(a: Stream[Int], b: Stream[Int]) -> Bool {
    a == b                            // ✗ a stream has no value to compare
}

fn same(a: Stream[Int], b: Stream[Int]) -> Effect[Bool] {
    let xs <- a.collect()             // ✓ read them first
    let ys <- b.collect()
    Effect.pure(xs == ys)
}
